/// Parses the bundled MADHEL snapshot into [ZoneData] circles.
List<ZoneData> loadBundledMadhelAerodromes() {
  final decoded = jsonDecode(_madhelSnapshotJson);
  if (decoded is! List) return const [];
  return MadhelZoneMapper.fromSnapshotJson(decoded);
}
